-- UrbanKart training database (fictional data) for the Data Analyst Course, Days 16-28
-- MySQL 8: run this whole file in MySQL Workbench (File > Open SQL Script, then the lightning button).

DROP DATABASE IF EXISTS urbankart;
CREATE DATABASE urbankart;
USE urbankart;

CREATE TABLE customers (
  customer_id VARCHAR(10) PRIMARY KEY,
  customer_name VARCHAR(60),
  gender VARCHAR(10),
  age_group VARCHAR(10),
  city VARCHAR(30),
  state VARCHAR(30),
  region VARCHAR(10),
  signup_date DATE,
  segment VARCHAR(10)
);


CREATE TABLE products (
  product_id VARCHAR(10) PRIMARY KEY,
  product_name VARCHAR(60),
  category VARCHAR(30),
  sub_category VARCHAR(30),
  cost_price INT,
  selling_price INT
);


CREATE TABLE orders (
  order_id VARCHAR(10) PRIMARY KEY,
  order_date DATE,
  customer_id VARCHAR(10),
  product_id VARCHAR(10),
  quantity INT,
  unit_price INT,
  discount_pct DECIMAL(4,2),
  sales INT,
  city VARCHAR(30),
  payment_mode VARCHAR(20),
  order_status VARCHAR(15),
  delivery_date DATE,
  FOREIGN KEY (customer_id) REFERENCES customers(customer_id),
  FOREIGN KEY (product_id) REFERENCES products(product_id)
);


CREATE TABLE order_returns (
  order_id VARCHAR(10) PRIMARY KEY,
  return_date DATE,
  return_reason VARCHAR(30),
  refund_amount INT,
  FOREIGN KEY (order_id) REFERENCES orders(order_id)
);


CREATE TABLE employees (
  employee_id VARCHAR(10) PRIMARY KEY,
  employee_name VARCHAR(60),
  gender VARCHAR(10),
  department VARCHAR(30),
  city VARCHAR(30),
  join_date DATE,
  monthly_salary INT,
  performance_rating INT,
  overtime VARCHAR(3),
  attrition VARCHAR(3),
  exit_date DATE
);


-- Check: should return 450, 60, 3288, 193, 300
SELECT (SELECT COUNT(*) FROM customers) AS customers, (SELECT COUNT(*) FROM products) AS products, (SELECT COUNT(*) FROM orders) AS orders,
       (SELECT COUNT(*) FROM order_returns) AS order_returns, (SELECT COUNT(*) FROM employees) AS employees;
